using UnityEngine;using LWS.TruckSports;
namespace LWS.TruckMinefield {
public sealed class MinefieldRacer:MonoBehaviour {
 public MinefieldMatch match;public SportsEventTruck truck;public int slot;public MineAttempt Phase{get;private set;}public Vector3 LaunchOrigin{get;private set;}public Vector3 LandingOrigin{get;private set;}public float LaunchTime{get;private set;}public float LandingTime{get;private set;}public bool Retired{get;private set;}public int Distance{get;private set;}=-1;public int Launches{get;private set;}public int LandingLocks{get;private set;}public float CorrectionSpent=>correction;public float FinishTime{get;private set;}=float.PositiveInfinity;
 float stalled,flight,correction,rangeGate;bool airborne,neutral;float priorZ;
 public void ResetAttempt(Vector3 p,bool active){Phase=active?MineAttempt.Driving:MineAttempt.Failed;Distance=-1;Launches=LandingLocks=0;Retired=false;LandingTime=0;FinishTime=float.PositiveInfinity;stalled=flight=correction=rangeGate=0;airborne=neutral=false;truck.slot=slot;truck.visuals.gameObject.SetActive(active);if(active){truck.Prepare(p,Quaternion.identity);truck.Power(false);truck.body.isKinematic=true;priorZ=truck.body.worldCenterOfMass.z;}else truck.Park(p+Vector3.down*40);}
 public void Release(){if(Phase!=MineAttempt.Driving)return;truck.body.isKinematic=false;truck.Power(true);}
 public bool Launch(Vector3 blast){if(!match.Live||match.Phase!=MinefieldPhase.Driving||Phase!=MineAttempt.Driving)return false;Phase=MineAttempt.Launched;Launches++;LaunchOrigin=truck.body.worldCenterOfMass;LaunchTime=match.HeatTime;truck.Power(false);var forward=Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up).normalized;if(forward.z<.3f)forward=(forward+Vector3.forward*1.5f).normalized;truck.body.AddForce(forward*(26+Mathf.Clamp(truck.body.linearVelocity.magnitude*.35f,0,8))+Vector3.up*27,ForceMode.VelocityChange);truck.body.AddTorque(new Vector3(2.5f,slot%2==0?1:-1,.8f),ForceMode.VelocityChange);match.Blast(this,blast);return true;}
 public void Step(Vector2 drive,float dt){if(Phase==MineAttempt.Driving){truck.grip=1.15f*match.weatherField.Grip;truck.TickDrive(drive);var center=truck.body.worldCenterOfMass;if(Mathf.Abs(center.x)<=55&&MinefieldRules.DrivenFinish(Phase,priorZ,center.z,out float fraction)){Phase=MineAttempt.DrivenFinish;FinishTime=match.HeatTime-dt+dt*fraction;truck.TickDrive(Vector2.zero);}priorZ=center.z;stalled=truck.body.linearVelocity.sqrMagnitude<.25f&&Mathf.Abs(drive.y)>.2f?stalled+dt:0;if(stalled>10||Mathf.Abs(center.x)>57||center.y< -15)Fail();}
 else if(Phase==MineAttempt.Landed){if(truck.body.position.y< -8||Mathf.Abs(truck.body.position.x)>306||truck.body.position.z>2087)Retire();}
 else if(Phase==MineAttempt.Launched){flight+=dt;rangeGate+=dt;if(!neutral&&Mathf.Abs(drive.y)<.12f)neutral=true;var input=new Vector2(drive.x,neutral?drive.y:0);float spent=Mathf.Min(input.magnitude*dt,Mathf.Max(0,2.2f-correction));correction+=spent;float gain=input.magnitude>.001f?spent/(input.magnitude*dt):0;truck.body.AddForce(new Vector3(input.x*2.3f,0,input.y*1.8f)*gain,ForceMode.Acceleration);truck.body.AddTorque(new Vector3(input.y*.5f,0,-input.x*.5f)*gain,ForceMode.Acceleration);airborne|=truck.body.worldCenterOfMass.y-match.GroundHeight(truck.body.position)>1.7f;if(truck.body.position.y< -15||flight>25)Fail();} }
 void Retire(){if(Retired)return;Retired=true;truck.Power(false);truck.body.isKinematic=true;truck.body.detectCollisions=false;truck.visuals.gameObject.SetActive(false);}
 public void Fail(){if(Phase==MineAttempt.Landed||Phase==MineAttempt.Failed||Phase==MineAttempt.DrivenFinish)return;Phase=MineAttempt.Failed;Distance=-1;Retire();}
 void OnCollisionEnter(Collision c){if(!match.Live)return;if(Phase==MineAttempt.Launched&&airborne&&flight>.12f&&c.collider is TerrainCollider){Phase=MineAttempt.Landed;LandingLocks++;LandingTime=match.HeatTime;LandingOrigin=truck.body.worldCenterOfMass;Distance=MinefieldRules.Precision(LandingOrigin.z);match.Landed(this);}}
}
}
